- x=2, y=3, a=6, b=18
- lcm(2,3) = 6
- floor(18/6) - floor(5/6) = 3 - 0 = 3 ✓

```c
#include <stdio.h>

long long gcd(long long a, long long b) {
    while (b) {
        long long t = b;
        b = a % b;
        a = t;
    }
    return a;
}

int main() {
    long long x, y, a, b;
    scanf("%lld %lld %lld %lld", &x, &y, &a, &b);

    long long g = gcd(x, y);
    long long lcm = x / g * y;

    long long count = b / lcm - (a - 1) / lcm;

    printf("%lld\n", count);

    return 0;
}
```

This is O(log(min(x,y))) time, well within limits.

