    scanf("%lld%lld", &a, &b);
    long long m = a < b ? a : b;
    long long result = 1;
    for(long long i = 2; i <= m; i++){
        result *= i;
    }
    printf("%lld", result);
    return 0;
}
```

This correctly handles all cases since min(A,B) ≤ 12, so the loop runs at most 12 times, and 12! = 479001600 fits easily in a long long.

