long long g[45], rest[45];
long long whole;

void dfs(long long mask, int cur, int cura) {
    if (cura >= best) return;
    if (mask == whole) { best = cura; return; }
    if (cur >= n * m) return;
    if ((mask | rest[cur]) != whole) return;
    dfs(mask | g[cur], cur + 1, cura + 1);
    dfs(mask, cur + 1, cura);
}

int main() {
    int i, j, k;
    scanf("%d%d", &n, &m);
    whole = (1LL << (n * m)) - 1;
    for (i = 0; i < n; ++i)
        for (j = 0; j < m; ++j)
            for (k = 0; k < 5; ++k) {
                int x = i + dx[k], y = j + dy[k];
                if (x < 0 || x >= n || y < 0 || y >= m) continue;
                g[i * m + j] |= 1LL << (x * m + y);
            }
    for (i = n * m - 1; i >= 0; --i) rest[i] = rest[i + 1] | g[i];
    best = n * m;
    dfs(0, 0, 0);
    printf("%d\n", n * m - best);
    return 0;
}
