void bfs_forward(char vis[]) {
    int head=0, tail=0;
    for(int i=0;i<n;i++) if(f[i]==1){vis[i]=1; queue[tail++]=i;}
    while(head<tail){
        int u=queue[head++];
        for(NODE*t=e[u];t;t=t->next){
            int w=t->v;
            if(!vis[w] && f[w]!=1){vis[w]=1; queue[tail++]=w;}
        }
    }
}

void bfs_backward(char vis[]) {
    int head=0, tail=0;
    for(int i=0;i<n;i++) if(f[i]==2){vis[i]=1; queue[tail++]=i;}
    while(head<tail){
        int u=queue[head++];
        for(NODE*t=b[u];t;t=t->next){
            int w=t->v;
            if(!vis[w] && f[w]!=1){vis[w]=1; queue[tail++]=w;}
        }
    }
}

int main(){
