package main

// https://codeforces.com/problemset/problem/723/A
// A. The New Year: Meeting Friends
// time limit per test
// 1 second
// memory limit per test
// 256 megabytes
// input
// standard input
// output
// standard output

// There are three friend living on the straight line Ox in Lineland. The first friend lives at the point x1, the second friend lives at the point x2, and the third friend lives at the point x3. They plan to celebrate the New Year together, so they need to meet at one point. What is the minimum total distance they have to travel in order to meet at some point and celebrate the New Year?

// It's guaranteed that the optimal answer is always integer.
// Input

// The first line of the input contains three distinct integers x1, x2 and x3 (1 ≤ x1, x2, x3 ≤ 100) — the coordinates of the houses of the first, the second and the third friends respectively.
// Output

// Print one integer — the minimum total distance the friends need to travel in order to meet together.

import (
    "bufio"
    "fmt"
    "os"
)

func main() {
    bufStdin := bufio.NewReader(os.Stdin)


    // the point at which the first would like to meet is is the midpoint
    // the midpoint of 2 points on a line is (p1+p2)/2
    // similarly, the midpoint of 3 points on a line is (p1+p2+p3)/3
    // in general, the midpoint of n points on a line is (p1+p2+...+pn)/n

    var x1, x2, x3 int
    _, _ = fmt.Fscan(bufStdin, &x1, &x2, &x3)

    midPoint := (x1+x2+x3)/3

    totalDist := intAbs(x1-midPoint) + intAbs(x2-midPoint) + intAbs(x3-midPoint)

    _, _ = fmt.Print(totalDist)
}

func intAbs(v int) int {
    if v < 0 {
        return -v
    }
    return v
}

