func Walk(v, c int) int { if tree[v].Walk[c] != -1 { return tree[v].Walk[c] }; if tree[v].Next[c] != -1 { tree[v].Walk[c] = tree[v].Next[c] } else if v == 0 { tree[v].Walk[c] = 0 } else { tree[v].Walk[c] = Walk(Getlink(v), c) }; return tree[v].Walk[c] }

