const readline = require('readline');
const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
  terminal: false
});

const gcd = (a, b) => {
  while (b !== 0) {
    const temp = a;
    a = b;
    b = temp % b;
  }

  return a;
}

const factorial = (n) => {
  let prev = 1;
  let r = prev;

  for (let i = 2; i <= n; i++) {
    r = prev * i;
    prev = r;
  }

  return r;
}

rl.on('line', (d) => {
  const [a, b] = d.split(' ').map(Number);

  console.log(gcd(factorial(a), factorial(b)));
});

