def simulate(balls, pos, color):
    # Insert ball at position pos
    new_balls = balls[:pos] + [color] + balls[pos:]
    original_len = len(balls)

    # Keep removing groups of 3+
    changed = True
    while changed:
        changed = False
        i = 0
        while i < len(new_balls):
            j = i
            while j < len(new_balls) and new_balls[j] == new_balls[i]:
                j += 1
            if j - i >= 3:
                new_balls = new_balls[:i] + new_balls[j:]
                changed = True
                break
            i = j

    return original_len - len(new_balls)

