import math

def solve():
    line = raw_input().split()
    l = int(line[0])
    r = int(line[1])
    x = int(line[2])
    y = int(line[3])

    if y % x != 0:
        print(0)
        return

    k = y // x

    # Find all divisors of k
    divisors = []
    i = 1
    while i * i <= k:
        if k % i == 0:
            divisors.append(i)
            if i != k // i:
                divisors.append(k // i)
        i += 1

    count = 0
    for d in divisors:
        q = k // d
        if math.gcd(d, q) == 1:
            a = x * d
            b = x * q
            if l <= a <= r and l <= b <= r:
                if a == b:
                    count += 1
                else:
                    count += 2

    print(count)

solve()

