import sys
from functools import lru_cache

a = raw_input()
n = len(a)

@lru_cache(maxsize=None)
def solve(i, has_at):
    if i == n:
        if has_at:
            return ""
        else:
            return None  # invalid - no @ used

    options = []

    # Option 1: take character as-is
    rest = solve(i+1, has_at)
    if rest is not None:
        options.append(a[i] + rest)

    # Option 2: replace 'dot' with '.' if valid position
    # Can't be at position 0 (start) or end (i+3 == n means dot would be at end -> result ends with '.')
    if a[i:i+3] == 'dot' and i > 0 and i+3 < n:
        rest = solve(i+3, has_at)
        if rest is not None:
            options.append('.' + rest)

    # Option 3: replace 'at' with '@' if valid and no @ used yet
    if a[i:i+2] == 'at' and i > 0 and i+2 < n and not has_at:
        rest = solve(i+2, True)
        if rest is not None:
            options.append('@' + rest)

    if not options:
        return None

    # Pick shortest, then lexicographically smallest
    best = min(options, key=lambda x: (len(x), x))
    return best

