            results.append('@' + rest)

    # Take current character as-is
    rest = dp(pos+1, has_at)
    if rest is not None:
        results.append(a[pos] + rest)

    if not results:
        return None

    results.sort(key=lambda x: (len(x), x))
    return results[0]

