import sys
from sys import stdin, stdout

def R():
    return map(int, stdin.readline().strip().split())

n, m, c0, d0 = R()

items = []
# Plain buns: can make at most n//c0
for i in range(n // c0):
    items.append((c0, d0))

for i in range(m):
    a, b, c, d = R()
    max_buns = min(a // b, n // c)
    for j in range(max_buns):
        items.append((c, d))

# 1D knapsack DP
dp = [0] * (n + 1)

for (c, d) in items:
