def congr(a, b, p, x):
    c = {}
    for i in range(0, p - 1):
        v = pow(a, i, p)
        if v not in c:
            c[v] = []
        c[v].append(i)

    inv_p_mod = pow(p % (p-1), p-2, p-1) if p > 2 else 1  # p mod(p-1) = 1, so inv=1
    # Actually p ≡ 1 (mod p-1), so inv_p mod(p-1) = 1

    s = 0
    period = p * (p - 1)
    for n1 in range(1, p):
        k = pow(n1, p - 2, p) * b % p
        if k not in c:
            continue
        for n2 in c[k]:
            # CRT: n ≡ n1 (mod p), n ≡ n2 (mod p-1)
            # n = n1 + p*t, need n1 + p*t ≡ n2 (mod p-1)
            # p ≡ 1 (mod p-1), so t ≡ n2 - n1 (mod p-1)
            t = (n2 - n1) % (p - 1)
            n = n1 + p * t
            if n < 1:
                n += period
            if n <= x:
                s += (x - n) // period + 1
    return s

