from math import comb

def prob(k, N):
    c_n_3 = comb(N, 3)
    if c_n_3 == 0:
        return 0.0
    p = 0.0
    # j=1
    if k >= 1 and N-k >= 2:
        p += comb(k,1)*comb(N-k,2)/c_n_3 * 0.5
    # j=2
    if k >= 2 and N-k >= 1:
        p += comb(k,2)*comb(N-k,1)/c_n_3 * 1.0
    # j=3
    if k >= 3:
        p += comb(k,3)/c_n_3 * 1.0
    return p

