    let mut ans = 0;

    while let Some((cur, removed)) = queue.pop_front() {
        ans = ans.max(removed);
        for i in 0..cur.len() {
            let can_remove = (i > 0 && cur[i] as u8 == cur[i-1] as u8 + 1) ||
                             (i + 1 < cur.len() && cur[i] as u8 == cur[i+1] as u8 + 1);
            if can_remove {
                let mut next = cur.clone();
                next.remove(i);
                if !visited.contains(&next) {
                    visited.insert(next.clone());
                    queue.push_back((next, removed + 1));
                }
            }
        }
    }

    println!("{}", ans);
}

