use std::collections::{HashSet, VecDeque};

fn can_remove(s: &Vec<char>, i: usize) -> bool {
    let c = s[i] as u8;
    if c == b'a' { return false; }
    let prev = c - 1;
    if i > 0 && s[i-1] as u8 == prev { return true; }
    if i + 1 < s.len() && s[i+1] as u8 == prev { return true; }
    false
}

fn main() {
    // read n and s
    let n: usize = { ... };
    let s: Vec<char> = { ... };

    let mut visited = HashSet::new();
    let mut queue = VecDeque::new();
    let initial = (s, 0usize);
    visited.insert(initial.0.clone());
    queue.push_back(initial);
    let mut ans = 0;

    while let Some((cur, removed)) = queue.pop_front() {
        ans = ans.max(removed);
        for i in 0..cur.len() {
            if can_remove(&cur, i) {
                let mut next = cur.clone();
                next.remove(i);
                if !visited.contains(&next) {
                    visited.insert(next.clone());
                    queue.push_back((next, removed + 1));
                }
            }
        }
    }

    println!("{}", ans);
}

