import java.util.*

val scanner = Scanner(System.`in`)

fun readString(): String = scanner.next()
fun readInt(): Int = scanner.nextInt()

fun maximize(number: String, swaps: Int): String {
    val digits = number.toCharArray()
    var k = swaps
    val n = digits.size

    for (i in 0 until n) {
        if (k == 0) break
        // Find max digit in range [i, min(i+k, n-1)]
        val end = minOf(i + k, n - 1)
        var maxIdx = i
        for (j in i + 1..end) {
            if (digits[j] > digits[maxIdx]) {
                maxIdx = j
            }
        }
        // Bubble digits[maxIdx] to position i
        val swapsUsed = maxIdx - i
        k -= swapsUsed
        // Shift elements
        val ch = digits[maxIdx]
        for (j in maxIdx downTo i + 1) {
            digits[j] = digits[j - 1]
        }
        digits[i] = ch
    }

    return String(digits)
}

fun main() = maximize(readString(), readInt()).run(::println)

