fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val parts = br.readLine().trim().split(" ")
    val n = parts[0].toLong()
    val k = parts[1].toLong()

    // Max pipes with all k-1 splitters: 1 + k*(k-1)/2
    // Check overflow: k can be 1e9, k*(k-1)/2 ~ 5e17, fits in Long
    val maxPipes = 1L + k * (k - 1L) / 2L

    if (maxPipes < n) {
