    var lo = 0L
    var hi = k - 1L

    while (lo < hi) {
        val mid = (lo + hi) / 2
        val pipes = 1L + mid * k - mid * (mid + 1L) / 2L
        if (pipes >= n) {
            hi = mid
        } else {
            lo = mid + 1L
        }
    }

    println(lo)
