private fun readLn() = readLine()!! // string line
private fun readStrings() = readLn().split(" ") // list of strings
private fun readInt() = readLn().toInt() // single int
private fun readInts() = readStrings().map { it.toInt() } // list of ints
private fun readLong() = readLn().toLong() // single long
private fun readLongs() = readStrings().map { it.toLong() } // list of longs
private fun readDouble() = readLn().toDouble() // single Double
private fun readDoubles() = readStrings().map { it.toDouble() } // list of doubles

fun solve(){
    var (n, m) = readInts()
    var arr = readInts()
    var n1 = n / 2; var n2 = n - n1

    var ans = 0
    var left = TreeSet<Int>()
    var right = TreeSet<Int>()
    for (mask in 0 until (1 shl n1)) {
        var sum = 0
        for (i in 0 until n1) {
            if ((mask and (1 shl i)) == (1 shl i)) sum = (sum + arr[i])%m
        }
        left.add(sum)
        ans = Math.max(ans, sum)
    }

    for (mask in 0 until (1 shl n2)) {
        var sum = 0
        for (i in 0 until n2) {
            if ((mask and (1 shl i)) == (1 shl i)) sum = (sum + arr[i + n1])%m
        }
        right.add(sum)
        ans = Math.max(sum, ans)
    }

    for (x in left) {
        var req = m - 1 - x
        var it = right.lower(req)
        if (it != null) {
            ans = Math.max(ans, (it + x)%m)
        }
        it = right.lower(req + m)
        if (it != null) {
            ans = Math.max(ans, (it + x)%m)
        }
    }

    println(ans)
}

