    val req = m - 1 - x
    val it = right.floor(req)
    if (it != null) {
        ans = Math.max(ans, (it + x) % m)
    }
    // Also try maximum element (handles wrap-around case)
    if (right.isNotEmpty()) {
        ans = Math.max(ans, (right.last() + x) % m)
